import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    MOD = 1000000007

    adj = defaultdict(list)

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        c = int(next(iterator))
        adj[u].append((v, c))
        adj[v].append((u, c))

    color = {}
    possible = True

    components = []

    for start_node in range(1, n + 1):
        if start_node in color:
            continue

        component_nodes = []
        stack = [start_node]
        color[start_node] = 0

        while stack:
            u = stack.pop()
            component_nodes.append(u)

            for v, c in adj[u]:
                expected_color = color[u] ^ (1 - c)
                if v not in color:
                    color[v] = expected_color
                    stack.append(v)
                elif color[v] != expected_color:
                    possible = False
                    break
            if not possible:
                break

        if not possible:
            break
        components.append(component_nodes)

    if not possible:
        print(0)
        return

    total_ways = 1

    for comp in components:
        size = len(comp)
        if size == 1:
            node = comp[0]
            ways = 2
        else:
            ways = 2

        total_ways = (total_ways * ways) % MOD

    print(total_ways)

if __name__ == "__main__":
    solve()
